@startuml

class Traveller {
  +name: string
  +billingInformation: string
  +travelPreferences: string[]
  +reliabilityRating: float
}

class Hotel {
  +name: string
  +address: string
  +rating: int
}

class City {
  +name: string
}

class HotelChain {
  +name: string
}

class RoomType {
  +type: string
}

class Availability {
  +period: string
  +isFull: boolean
}

class SearchCriteria {
  +city: string
  +arrivalDate: date
  +departureDate: date
  +numberOfRooms: int
  +roomType: string
  +minRating: int
  +maxCostPerNight: float
  +preferences: string[]
}

class PreliminaryBooking {
  +bookingIdentifier: string
  +price: float
  +cityArea: string
  +hotelRating: int
  +preferences: string[]
}

class SpecialOffer {
  +price: float
}

class Booking {
  +bookingIdentifier: string
  +cancellationDeadline: date
  +isPrePaid: boolean
  +isConfirmed: boolean
}

class CreditCardInfo {
  +cardNumber: string
}

Hotel "0..*" -- "1" City
Hotel "0..*" -- "0..1" HotelChain
Hotel "1" -- "*" Availability
Hotel "1" -- "*" RoomType
Hotel "1" -- "*" Booking

Traveller "1" -- "*" PreliminaryBooking
Traveller "1" -- "*" Booking
Traveller "1" -- "0..*" CreditCardInfo

PreliminaryBooking "1" -- "0..*" SpecialOffer
PreliminaryBooking "1" -- "0..1" Booking : proceeds to

Hotel "1" -- "0..*" SpecialOffer : provides

Booking "1" -- "1" CreditCardInfo : finalized with

@enduml

